package awsmodels

import (
	_ "embed"
	"encoding/json"
	"sync"
)

// datasync/model.json is generated by scripts/gen-glue-model.py
// (AWS_MODEL_SERVICE=datasync) from the AWS CLI's bundled botocore model.
//
//go:embed datasync/model.json
var dataSyncModelJSON []byte

var (
	dataSyncModelOnce sync.Once
	dataSyncModel     *ServiceModel
)

// DataSyncModel returns the shared, read-only DataSync model.
func DataSyncModel() *ServiceModel {
	dataSyncModelOnce.Do(func() {
		var m ServiceModel
		if err := json.Unmarshal(dataSyncModelJSON, &m); err != nil {
			panic("awsmodels: invalid datasync model: " + err.Error())
		}
		dataSyncModel = &m
	})
	return dataSyncModel
}
